\draw[asymptotered,dashed,thick] (-3,2)--(1.2,2);
\path (-2,2) node[above] {$y=2$};
\draw[curveblue,thick,<->,domain=-3:1.15,samples=100,smooth,variable=\x] plot ({\x},{2-exp(\x*ln(4))});
\fill[black] (0,1) circle (1.5pt);
\path (0,1) node[above right] {$(0,1)$};
\end{tikzpicture}
[/tikz]

